const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),lerp=(a,b,t)=>a+(b-a)*t;
function root(w,f){let i=clamp(Math.floor(f),0,433),j=Math.min(i+1,433),u=f-i;return [lerp(SPRITES[w][i][7],SPRITES[w][j][7],u),lerp(SPRITES[w][i][8],SPRITES[w][j][8],u)];}
function ballAt(f){let i=1;while(i<BALL.length-1&&BALL[i][0]<f)i++;let a=BALL[i-1],b=BALL[i],u=clamp((f-a[0])/(b[0]-a[0]),0,1);return [lerp(a[1],b[1],u),lerp(a[2],b[2],u)];}
// Estimate the shutter velocity within one physical flight leg. A collision
